using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "VortexBubbleCustomTag", menuName = "Data/Battle/Battle Actions/Tags/VortexBubbleCustomTag", order = 0)]
public class VortexBubbleCustomTag : Tag
{
	private const string vortexBubbleTagBaseDescriptionID = "VortexBubbleTagBaseDescription";

	[SerializeField]
	private VortexBubbleEffect vortexBubbleEffect;

	public override string GetTagDescription()
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("VortexBubbleTagBaseDescription"), Smart.Format(base.GetTagDescription(), 99), vortexBubbleEffect.GetEffectName(), ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedPurifyOrCorruptionWord(!vortexBubbleEffect.CorruptedBubble), vortexBubbleEffect.PurifyCorruptAmountToTrigger);
	}
}
